def shortest_path_bfs(graph: dict, start: str, goal: str) -> int:
    q = deque([(start, 0)])
    visited = {start}
    while q:
        node, dist = q.popleft()
        if node == goal:
            return dist
        for nei in graph.get(node, []):
            if nei not in visited:
                visited.add(nei)
                q.append((nei, dist + 1))
    return -1

